import { Component, inject, NgZone, OnInit, signal } from '@angular/core';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { AuthenticationService } from '../../userservices/authentication.service';
import { first } from 'rxjs';

@Component({
  selector: 'user-settings',
  imports: [ReactiveFormsModule, RouterModule],
  templateUrl: './user-settings.html',
  styleUrl: './user-settings.css',
})
export class UserSettings implements OnInit {

  private formBuilder: FormBuilder = inject(FormBuilder);
  private route: ActivatedRoute = inject(ActivatedRoute);
  private router: Router = inject(Router);
  private authenticationService: AuthenticationService = inject(AuthenticationService);
  private zone: NgZone = inject(NgZone);

  userSettings: Array<{ name: string, selected: boolean, description: string }> = [
    { name: 'credential', selected: true, description: 'Save my login to this browser for future and allow me auto login.' },
    { name: 'email', selected: true, description: 'Send me the emails for Login, account updates on my personal email.' },
    { name: 'notification', selected: true, description: 'Send me the event and offers to my personal email.' },
    { name: 'contact', selected: false, description: 'Contact me via phone calls for promotion and offers.' },
    { name: 'reminder', selected: true, description: 'Remiend me to schedule events based on my usages history.' }
  ];

  settingForm: FormGroup;

  loading = signal<boolean>(false);
  submitted = signal<boolean>(false);
  returnUrl: string | null = null;

  constructor() {
    let user = this.authenticationService.currentUserValue;
    this.settingForm = this.formBuilder.group({
      credential: [user?.credential, Validators.required],
      email: [user?.email, [Validators.email, Validators.required]],
      notification: [user?.notification, [Validators.required, Validators.minLength(10)]],
      contact: [user?.contact, Validators.required],
      reminder: [user?.reminder, Validators.required],
    });
  }

  get f() { return this.settingForm?.controls; };

  ngOnInit(): void {
    this.returnUrl = this.route.snapshot.queryParams['returnUrl'] || '/user/dashboard';
  }

  onSubmit() {
    this.submitted.set(true);
    this.loading.set(true);
    this.authenticationService.updateUserSettings(this.f['credential'].value, this.f['email'].value, this.f['notification'].value, this.f['contact'].value, this.f['reminder'].value)
      .pipe(first())
      .subscribe({
        next: (data) => {
          if (data['success']) {
            //this.alertService.success(data['ops']);
            this.zone.run(() => {
              this.loading.set(false);
              this.router.navigate([this.returnUrl]);
            })
          } else {
            //this.alertService.error(data['ops']);
            this.loading.set(false);
          }
        },
        error: (error) => {
          //this.alertService.error(error);
          this.loading.set(false);
        },
        complete: () => { this.loading.set(false) }
      }
      );
  }

}
